// versionSegment appends an already-validated keyspace suffix to a schema version. An
// empty suffix leaves the version untouched, which is what keeps an unconfigured
// galactus byte-identical to its historical keys.
func versionSegment(version, suffix string) string {
	if suffix == "" {
		return version
	}
	return version + "-" + suffix
}

// registerAllowedVersions teaches nexus-proto's validator about the derived versions.
// validator.ValidateKeyPath rejects any version outside validator.AllowedVersions, and
// galactus calls it before every Delete/Deregister and when scanning endpoints -- so
// without this a suffixed keyspace would be written but never read back or cleaned up.
func registerAllowedVersions(versions ...string) {
	for _, v := range versions {
		if slices.Contains(validator.AllowedVersions, v) {
			continue
		}
		validator.AllowedVersions = append(validator.AllowedVersions, v)
	}
}

// PutLRCSpec writes an LRC spec to etcd.
// The key must be under the LRCPrefix subtree.
func (a *AdapterV2) PutLRCSpec(key string, value []byte) error {
	if a.Client == nil {
		return errors.New("etcd client is nil")
	}
	if !strings.HasPrefix(key, LRCPrefix+"/") {
		return fmt.Errorf("PutLRCSpec: key %q is outside the LRC prefix", key)
	}
	ctx, cancel := context.WithTimeout(a.ctx, 5*time.Second)
	defer cancel()
	_, err := a.Client.Put(ctx, key, string(value))
	if err != nil {
		return fmt.Errorf("failed to put LRC spec to etcd: %w", err)
	}
	return nil
}

// DeleteLRCSpec deletes an LRC spec from etcd.
// The key must be under the LRCPrefix subtree.
func (a *AdapterV2) DeleteLRCSpec(key string) error {
	if a.Client == nil {
		return errors.New("etcd client is nil")
	}
	if !strings.HasPrefix(key, LRCPrefix+"/") {
		return fmt.Errorf("DeleteLRCSpec: key %q is outside the LRC prefix", key)
	}
	ctx, cancel := context.WithTimeout(a.ctx, 5*time.Second)
	defer cancel()
	_, err := a.Client.Delete(ctx, key)
	if err != nil {
		return fmt.Errorf("failed to delete LRC spec from etcd: %w", err)
	}
	return nil
}

// Close closes the etcd client connection if it is not nil.
func (a *AdapterV2) Close() {
	if a.Client != nil {
		a.Client.Close()
	}
	if a.SecondaryClient != nil {
		a.SecondaryClient.Close()
	}
}

