func (m *MockAdapterV2) GetEndpointsPodUIDs() (map[string]string, error) {
	// Return an empty map by default (no stored UIDs) unless a test sets an
	// explicit expectation, so existing Clean() tests need no extra wiring.
	for _, call := range m.ExpectedCalls {
		if call.Method == "GetEndpointsPodUIDs" {
			args := m.Called()
			// Nil-guard: a test configuring .Return(nil, err) must reach the
			// production error path, not panic on this type assertion.
			if args.Get(0) == nil {
				return nil, args.Error(1)
			}
			return args.Get(0).(map[string]string), args.Error(1)
		}
	}
	return map[string]string{}, nil
